INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 3, 'theory', 'Quiz: data types');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 3, 0, 'What type does the variable get in let n = 7;?', '["i64", "usize", "i32", "u8"]', 2, 'Without hints, integers are inferred as i32 and floats as f64.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 3, 1, 'What does 7 / 2 give for integers?', '["3.5", "3", "4", "a compile error"]', 1, 'Integer division throws away the fractional part. To get 3.5, at least one number must be a float: 7.0 / 2.0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 3, 2, 'What happens in a debug build if you add 1 to a u8 holding 255?', '["a panic because of overflow", "the result silently becomes 0", "the result becomes 256", "always a compile error"]', 0, 'In debug, overflow is a panic; in release the value wraps around. To make the behavior independent of the mode, use checked_add, wrapping_add, or saturating_add.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 3, 3, 'What do you need to write to add a: i32 and b: i64?', '["just a + b", "a + b as i32 is not possible at all", "add mut", "convert one of the operands: i64::from(a) + b"]', 3, 'Rust does not mix numeric types automatically: convert explicitly, with From, as, or try_from.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 3, 4, 'Why can''t you write if 1 { … } in Rust?', '["because 1 is not a number", "the condition must be of type bool: numbers have no truthiness", "because of compiler limitations", "because if accepts only strings"]', 1, 'A condition must be a bool: write an explicit comparison, for example if n != 0.');
